body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

.container {
    width: 100%;
    max-width: 500px;
}

.form-wrapper {
    background: white;
    border-radius: 12px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.08);
    padding: 40px;
}

h1 {
    font-size: 28px;
    font-weight: 700;
    color: #1a1a1a;
    margin-bottom: 8px;
    letter-spacing: -0.5px;
}

.subtitle {
    font-size: 14px;
    color: #666;
    margin-bottom: 32px;
    line-height: 1.5;
}

.contact-form {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

label {
    font-size: 14px;
    font-weight: 600;
    color: #1a1a1a;
    display: flex;
    align-items: center;
    gap: 4px;
}

.required {
    color: #e74c3c;
    font-weight: 700;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
    padding: 12px 14px;
    font-size: 14px;
    border: 1.5px solid #e0e0e0;
    border-radius: 8px;
    font-family: inherit;
    transition: all 0.2s ease;
    background-color: #fafafa;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus {
    outline: none;
    border-color: #3b82f6;
    background-color: white;
    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

input[type="text"].error,
input[type="email"].error,
input[type="tel"].error {
    border-color: #e74c3c;
    background-color: #fff5f5;
}

input[type="text"].error:focus,
input[type="email"].error:focus,
input[type="tel"].error:focus {
    box-shadow: 0 0 0 3px rgba(231, 76, 60, 0.1);
}

.helper-text {
    font-size: 12px;
    color: #888;
    line-height: 1.4;
}

.error-message {
    font-size: 12px;
    color: #e74c3c;
    font-weight: 500;
    min-height: 16px;
    display: none;
}

.error-message.show {
    display: block;
}

.submit-button {
    padding: 12px 24px;
    font-size: 14px;
    font-weight: 600;
    color: white;
    background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
    border: none;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s ease;
    margin-top: 8px;
}

.submit-button:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(59, 130, 246, 0.3);
}

.submit-button:active {
    transform: translateY(0);
}

.submit-button:disabled {
    background: #cbd5e1;
    cursor: not-allowed;
    transform: none;
}

.success-message {
    padding: 16px 14px;
    background-color: #ecfdf5;
    border: 1.5px solid #10b981;
    border-radius: 8px;
    color: #047857;
    font-size: 14px;
    font-weight: 500;
    text-align: center;
}

@media (max-width: 480px) {
    .form-wrapper {
        padding: 24px;
    }

    h1 {
        font-size: 24px;
    }

    .subtitle {
        margin-bottom: 24px;
    }

    .contact-form {
        gap: 20px;
    }
}
