    init() {
        if (!this.form) return;

        this.form.addEventListener('submit', (e) => this.handleSubmit(e));

        const inputs = this.form.querySelectorAll('input[required]');
        inputs.forEach(input => {
            input.addEventListener('blur', () => {
                this.hasInteracted.add(input.name);
                this.validateField(input);
            });

            input.addEventListener('input', () => {
                if (this.hasInteracted.has(input.name)) {
                    this.validateField(input);
                }
            });
        });

        const phoneInput = this.form.querySelector('input[name="phone"]');
        if (phoneInput) {
            phoneInput.addEventListener('blur', () => {
                this.hasInteracted.add('phone');
                this.validateField(phoneInput);
            });

            phoneInput.addEventListener('input', () => {
                if (this.hasInteracted.has('phone')) {
                    this.validateField(phoneInput);
                }
            });
        }
    }

    validateField(input) {
        const fieldName = input.name;
        const value = input.value.trim();
        let isValid = true;
        let errorMessage = '';

        if (fieldName === 'fullName') {
            if (value === '') {
                isValid = false;
                errorMessage = 'Full name is required';
            } else if (value.length < 2) {
                isValid = false;
                errorMessage = 'Full name must be at least 2 characters';
            }
        } else if (fieldName === 'email') {
            if (value === '') {
                isValid = false;
                errorMessage = 'Email address is required';
            } else if (!this.isValidEmail(value)) {
                isValid = false;
                errorMessage = 'Please enter a valid email address';
            }
        } else if (fieldName === 'phone') {
            if (value !== '' && !this.isValidPhone(value)) {
                isValid = false;
                errorMessage = 'Please enter a valid phone number';
            }
        }

        this.setFieldState(input, isValid, errorMessage);
        return isValid;
    }

    isValidEmail(email) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    }

    isValidPhone(phone) {
        // Allow various phone formats with digits and common symbols
        const phoneRegex = /^[+]?[(]?[0-9]{1,4}[)]?[-\s.]?[(]?[0-9]{1,4}[)]?[-\s.]?[0-9]{1,9}$/;
        return phoneRegex.test(phone);
    }

    setFieldState(input, isValid, errorMessage) {
        const errorElement = this.form.querySelector(`.error-message[data-field="${input.name}"]`);

        if (isValid) {
            input.classList.remove('error');
            if (errorElement) {
                errorElement.classList.remove('show');
                errorElement.textContent = '';
            }
        } else {
            input.classList.add('error');
            if (errorElement) {
                errorElement.classList.add('show');
                errorElement.textContent = errorMessage;
            }
        }
    }

    validateForm() {
        const fullNameInput = this.form.querySelector('input[name="fullName"]');
        const emailInput = this.form.querySelector('input[name="email"]');
        const phoneInput = this.form.querySelector('input[name="phone"]');

        this.hasInteracted.add('fullName');
        this.hasInteracted.add('email');
        this.hasInteracted.add('phone');

        const isFullNameValid = this.validateField(fullNameInput);
        const isEmailValid = this.validateField(emailInput);
        const isPhoneValid = this.validateField(phoneInput);

        return isFullNameValid && isEmailValid && isPhoneValid;
    }

    handleSubmit(e) {
        e.preventDefault();

        if (!this.validateForm()) {
            return;
        }

        const formData = {
            fullName: this.form.querySelector('input[name="fullName"]').value.trim(),
            email: this.form.querySelector('input[name="email"]').value.trim(),
            phone: this.form.querySelector('input[name="phone"]').value.trim(),
        };

        console.log('Form submitted with data:', formData);

        // Show success message
        this.form.style.display = 'none';
        document.getElementById('successMessage').style.display = 'block';

        // Reset form after 3 seconds
        setTimeout(() => {
            this.form.reset();
            this.form.style.display = 'flex';
            document.getElementById('successMessage').style.display = 'none';
            this.hasInteracted.clear();

            const inputs = this.form.querySelectorAll('input');
            inputs.forEach(input => {
                input.classList.remove('error');
                const errorElement = this.form.querySelector(`.error-message[data-field="${input.name}"]`);
                if (errorElement) {
                    errorElement.classList.remove('show');
                    errorElement.textContent = '';
                }
            });
        }, 3000);
    }
}

